package com.fasterxml.jackson.databind.module;

import com.fasterxml.jackson.databind.AbstractTypeResolver;
import com.fasterxml.jackson.databind.DeserializationConfig;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.type.ClassKey;
import com.fasterxml.jackson.databind.type.TypeFactory;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.Modifier;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.mockito.Mockito.mock;

public class SimpleAbstractTypeResolver_findTypeMapping_TriageGen1Test {

    private SimpleAbstractTypeResolver resolver;
    private DeserializationConfig config;
    private TypeFactory typeFactory;

    @Before
    public void setUp() {
        resolver = new SimpleAbstractTypeResolver();
        config = mock(DeserializationConfig.class);
        // Use a real ObjectMapper to get a real TypeFactory for JavaType operations
        typeFactory = new ObjectMapper().getTypeFactory();
    }



    @Test
    public void testFindTypeMapping_ReturnsNarrowedTypeWhenMappingExists() {
        // Arrange
        // Mapping: Iterable.class -> java.util.ArrayList.class
        resolver.addMapping(Iterable.class, java.util.ArrayList.class);

        // We use a type that represents the source class (Iterable)
        JavaType type = typeFactory.constructType(Iterable.class);

        // Act
        JavaType result = resolver.findTypeMapping(config, type);

        // Assert
        // The result should be a JavaType that is "narrowed" to ArrayList
        // narrowBy() returns a new JavaType with the same properties but the new raw class
        assertEquals("The returned type should be narrowed to ArrayList", 
                java.util.ArrayList.class, result.getRawClass());
        assertEquals("The type should match the destination class", 
                typeFactory.constructType(java.util.ArrayList.class), result);
    }




}

package com.fasterxml.jackson.databind.module;

